prompt --application/shared_components/user_interface/templates/region/kinetic_title
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(467825608289781451)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TKineticTitle #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TKineticTitle-header">',
'    <span class="amc-TKineticTitle-ghost" aria-hidden="true">#TITLE#</span>',
'    <div class="amc-TKineticTitle-kicker">',
'      <span class="amc-TKineticTitle-eyebrow" aria-hidden="true"><span class="amc-TKineticTitle-icon fa #ICON_CSS_CLASSES#"></span><span class="amc-TKineticTitle-tick"></span></span>',
'      <div class="amc-TKineticTitle-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </div>',
'    <h2 class="amc-TKineticTitle-title" id="#REGION_STATIC_ID#_heading"><span class="amc-TKineticTitle-ink">#TITLE#</span></h2>',
'    <span class="amc-TKineticTitle-rule" aria-hidden="true"></span>',
'  </header>',
'  <div class="amc-TKineticTitle-sheet">',
'    <div class="amc-TKineticTitle-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TKineticTitle-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Kinetic Title'
,p_internal_name=>'AMC_TPL_KINETIC_TITLE'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-kinetic-title.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template with oversized kinetic type. The region title is set very large as outlined letters; when the pointer is over the region or anything inside it has keyboard focus, color wipes into the letters from the reading start edge and the accent on the rule grows. The region icon is a small eyebrow above the title; buttons in Help, Edit, Change, Copy, Delete and Create sit at the end of the eyebrow line and Previous, Close and Next in the footer. The native content sits on a plain surface sheet below the rule. Template options: Giant ghost title repeats the title huge and faint behind the header, Solid title starts filled in the text color and wipes to the accent color, Huge title makes it larger still, Ink fill wipes in the text color instead of the palette gradient, and No body padding. Short titles work best; long titles wrap. Under reduced motion the fill changes without the wipe; in forced-colors mode the title is plain solid text.'
);
end;
